"""Generate the four app-demo scenes (s4–s7) from one layout.

Layout: app window (left, 1380 px) playing real screen recordings, with
punch-in zooms; a right rail (the workflow mini-map lives above it in the
overlay composition) holding a "now running" step card synced to the VO.
Run: python3 _build/gen_app_scenes.py   (from 06-film/)
"""
import json, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
WIN = dict(left=90, top=150, w=1380, title=46)
WIN["h"] = round(WIN["w"] * 1080 / 1920)  # 776

FONTS = """
        @font-face { font-family: "Instrument Serif"; src: url("../assets/fonts/instrument-serif-latin-400-normal.woff2") format("woff2"); font-weight: 400; }
        @font-face { font-family: "Instrument Serif"; src: url("../assets/fonts/instrument-serif-latin-400-italic.woff2") format("woff2"); font-style: italic; }
        @font-face { font-family: "Geist"; src: url("../assets/fonts/geist-sans-latin-400-normal.woff2") format("woff2"); font-weight: 400; }
        @font-face { font-family: "Geist"; src: url("../assets/fonts/geist-sans-latin-500-normal.woff2") format("woff2"); font-weight: 500; }
        @font-face { font-family: "Geist"; src: url("../assets/fonts/geist-sans-latin-700-normal.woff2") format("woff2"); font-weight: 700; }
        @font-face { font-family: "Geist Mono"; src: url("../assets/fonts/geist-mono-latin-500-normal.woff2") format("woff2"); font-weight: 500; }"""

SCENES = {
    "s4-l1": dict(
        dur=14, chapter=("L1", "Principles", "#0f3d75"), url="dixi · /dashboard/new → cn/5-series",
        base=None,
        clips=[("rec-01-l1.mp4", 2.8, 11.2, 1.5, 1.22)],
        punches=[(9.6, 12.9, 960, 690, 1.55)],
        steps=[(4.0, "#0f3d75", "NOW RUNNING · L1", "Principles first", "Years of BMW market knowledge, owned by product managers. Every analysis starts here.")],
    ),
    "s5-l2": dict(
        dur=38, chapter=("L2", "Evidence", "#1c69d4"), url="dixi · /dashboard/cn/5-series",
        base=None,
        clips=[("rec-02-l2-list.mp4", 3.6, 16.6, 0.0, 1.0), ("rec-03-l2-decide.mp4", 20.2, 17.8, 0.0, 0.93)],
        punches=[(5.0, 12.6, 780, 620, 1.32), (15.6, 20.0, 1700, 420, 1.6), (26.6, 31.8, 960, 560, 1.55), (33.5, 37.6, 1250, 430, 1.42)],
        steps=[
            (4.5, "#1c69d4", "NOW RUNNING · L2", "Feature requests, scored", "Customer feedback, trends and competitors, clustered into requests. Top of the list is the priority."),
            (15.5, "#1c69d4", "NOW RUNNING · L2", "Every source, one click away", "The quotes, markets and channels behind each request. Nothing is a black box."),
            (22.6, "#e22718", "HUMAN GATE", "The product manager decides", "Keep, or reject. A reason is required, and it is recorded with name and time."),
            (33.4, "#e22718", "DECISION MEMORY", "Remembered next time", "The reason is stored and shapes the next generation of requests."),
        ],
    ),
    "s6-l3": dict(
        dur=30, chapter=("L3", "Profiles & signals", "#5aa9f0"), url="dixi · /dashboard/generations",
        base="assets/stills/cn-profiles.png",
        clips=[("rec-04-l3-profiles.mp4", 3.2, 3.0, 5.5, 1.0), ("rec-04-l3-profiles.mp4", 6.2, 5.0, 14.0, 0.95), ("rec-05-l3-social.mp4", 18.0, 12.0, 1.0, 1.0)],
        punches=[(8.4, 11.2, 1080, 520, 1.4), (22.0, 26.4, 1000, 640, 1.45)],
        steps=[
            (4.0, "#5aa9f0", "NOW RUNNING · L3", "Three profiles, scored", "Built only from what you kept, each with its L1 · L2 · L3 score."),
            (8.3, "#5aa9f0", "NOW RUNNING · L3", "Why every spec is there", "Every line traces back to customer mentions, principles and your decisions."),
            (19.0, "#5aa9f0", "NOW RUNNING · L3", "Tested on social media", "Simulated 14-day reach and engagement for each profile's story."),
            (23.3, "#5aa9f0", "SIGNAL WEIGHT", "Noisy, so it weighs least", "Social response nudges the ranking. It never decides on its own."),
        ],
        popup=dict(src="../assets/video/m350.mp4", start=12.8, dur=5.8, label="One story per profile", credit="Film: BMW M350 xDrive Sedan © BMW M · shown for this pitch only"),
    ),
    "s7-weights": dict(
        dur=18, chapter=("Weights", "You set them", "#1c69d4"), url="dixi · /dashboard/settings",
        base=None,
        clips=[("rec-06-weights.mp4", 4.2, 13.8, 1.4, 1.3)],
        punches=[(4.4, 6.6, 780, 700, 1.5), (6.7, 11.9, 780, 480, 1.6), (12.2, 15.6, 780, 560, 1.45), (16.1, 18.0, 800, 580, 1.6)],
        steps=[
            (4.4, "#1c69d4", "SOURCE WEIGHTS", "Every weight is yours", "Move a slider, or say what matters in plain words."),
            (12.2, "#1c69d4", "AI PROPOSES · YOU APPLY", "Demand 70% → 80%", "Market backing 25% → 15%. Nothing changes until the PM applies it."),
            (16.1, "#1c69d4", "AUDIT TRAIL", "Every change is logged", "Who, when, what changed and why."),
        ],
    ),
}


def build(sid, s):
    W = WIN
    vids = []
    for i, (src, start, dur, ms, rate) in enumerate(s["clips"]):
        vids.append(
            f'<video id="{sid}-v{i}" src="../assets/rec/{src}" muted playsinline data-start="{start}" data-duration="{dur}" '
            f'data-media-start="{ms}" data-playback-rate="{rate}" data-track-index="{i + 1}"></video>'
        )
    base = f'<img class="base" src="../{s["base"]}" alt="" />' if s["base"] else ""
    steps_html = "".join(
        f'<div class="step" id="{sid}-st{i}"><div class="k" style="color:{c}">{k}</div><div class="t">{t}</div><div class="d">{d}</div></div>'
        for i, (_, c, k, t, d) in enumerate(s["steps"])
    )
    ch_id, ch_name, ch_col = s["chapter"]
    popup = ""
    if s.get("popup"):
        p = s["popup"]
        popup = f'''
        <div id="{sid}-pop-dim"></div>
        <div id="{sid}-pop"><div id="{sid}-pop-in">
          <video id="{sid}-pv" src="{p["src"]}" muted playsinline data-start="{p["start"]}" data-duration="{p["dur"]}" data-track-index="9"></video>
        </div>
          <div id="{sid}-pop-label">{p["label"]}</div>
          <div id="{sid}-pop-credit">{p["credit"]}</div>
        </div>'''
    css = f"""
        #root {{ position: absolute; inset: 0; background: #f5f7fb; overflow: hidden; font-family: "Geist", sans-serif; color: #0d1b2a; }}
        #{sid}-grid {{ position: absolute; inset: 0; opacity: .5; background-image: linear-gradient(#dfe6f0 2px, transparent 2px), linear-gradient(90deg, #dfe6f0 2px, transparent 2px); background-size: 120px 120px; }}
        #{sid}-chap {{ position: absolute; left: {W["left"]}px; top: 62px; display: flex; align-items: center; gap: 18px; }}
        #{sid}-chap .tag {{ font-family: "Geist Mono", monospace; font-size: 24px; letter-spacing: .1em; color: #fff; background: {ch_col}; padding: 8px 16px; border-radius: 10px; }}
        #{sid}-chap .nm {{ font-family: "Instrument Serif", serif; font-size: 58px; letter-spacing: -0.01em; }}
        #{sid}-win {{ position: absolute; left: {W["left"]}px; top: {W["top"]}px; width: {W["w"]}px; height: {W["h"] + W["title"]}px; background: #fff; border: 2px solid #d5dde8; border-radius: 22px; overflow: hidden; box-shadow: 0 40px 90px -36px rgba(13,27,42,.42); }}
        #{sid}-bar {{ height: {W["title"]}px; display: flex; align-items: center; gap: 10px; padding: 0 20px; background: #eef2f8; border-bottom: 2px solid #dfe6f0; }}
        #{sid}-bar .d {{ width: 13px; height: 13px; border-radius: 50%; background: #c9d4e3; }}
        #{sid}-bar .u {{ margin-left: 18px; font-family: "Geist Mono", monospace; font-size: 18px; color: #6b7a8f; }}
        #{sid}-view {{ position: absolute; left: 0; top: {W["title"]}px; width: {W["w"]}px; height: {W["h"]}px; overflow: hidden; background: #fff; }}
        #{sid}-zoom {{ position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; transform-origin: 0 0; }}
        #{sid}-zin {{ position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }}
        #{sid}-zin video, #{sid}-zin .base {{ position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; object-fit: cover; }}
        #{sid}-rail {{ position: absolute; left: 1500px; top: 372px; width: 380px; height: 600px; }}
        .step {{ position: absolute; left: 0; top: 0; width: 380px; opacity: 0; }}
        .step .k {{ font-family: "Geist Mono", monospace; font-size: 20px; letter-spacing: .12em; }}
        .step .t {{ margin-top: 12px; font-family: "Instrument Serif", serif; font-size: 50px; line-height: 1.04; color: #0d1b2a; }}
        .step .d {{ margin-top: 16px; font-size: 25px; line-height: 1.38; color: #3b4a5c; }}
        #{sid}-railhead {{ position: absolute; left: 1500px; top: 112px; font-family: "Geist Mono", monospace; font-size: 18px; letter-spacing: .14em; color: #6b7a8f; }}
        #{sid}-pop-dim {{ position: absolute; inset: 0; background: rgba(13,27,42,.55); opacity: 0; }}
        #{sid}-pop {{ position: absolute; left: 400px; top: 170px; width: 1120px; height: 720px; opacity: 0; }}
        #{sid}-pop-in {{ position: absolute; left: 0; top: 0; width: 1120px; height: 630px; border-radius: 26px; overflow: hidden; border: 5px solid #fff; box-shadow: 0 60px 120px -30px rgba(0,0,0,.7); background: #000; }}
        #{sid}-pop-in video {{ width: 100%; height: 100%; object-fit: cover; }}
        #{sid}-pop-label {{ position: absolute; left: 0; top: 650px; font-family: "Instrument Serif", serif; font-size: 48px; color: #fff; }}
        #{sid}-pop-credit {{ position: absolute; right: 0; top: 668px; font-size: 18px; color: #d5dde8; }}"""
    js = [f'const tl = gsap.timeline({{ paused: true }});',
          f'const wl = {W["w"] / 1920};',
          f'gsap.set("#{sid}-zoom", {{ scale: wl }});']
    js.append(f'tl.fromTo("#{sid}-chap", {{ opacity: 0, x: -30 }}, {{ opacity: 1, x: 0, duration: 0.6, ease: "power3.out" }}, 0.3);')
    js.append(f'tl.fromTo("#{sid}-win", {{ opacity: 0, y: 50, scale: 0.97 }}, {{ opacity: 1, y: 0, scale: 1, duration: 0.8, ease: "power3.out" }}, 0.2);')
    js.append(f'tl.fromTo("#{sid}-railhead", {{ opacity: 0 }}, {{ opacity: 1, duration: 0.5 }}, 0.8);')
    for i, (a, b, px, py, S) in enumerate(s["punches"]):
        # punch toward (px,py): scale the inner layer about that point
        js.append(f'tl.fromTo("#{sid}-zin", {{ scale: 1, x: 0, y: 0 }}, {{ scale: {S}, x: {-(S - 1) * px:.1f}, y: {-(S - 1) * py:.1f}, duration: 0.7, ease: "expo.inOut", immediateRender: {"true" if i == 0 else "false"} }}, {a});')
        js.append(f'tl.to("#{sid}-zin", {{ scale: 1, x: 0, y: 0, duration: 0.6, ease: "expo.inOut" }}, {b - 0.6});')
    for i, (t, *_rest) in enumerate(s["steps"]):
        js.append(f'tl.fromTo("#{sid}-st{i}", {{ opacity: 0, y: 24 }}, {{ opacity: 1, y: 0, duration: 0.55, ease: "power3.out" }}, {t});')
        if i + 1 < len(s["steps"]):
            js.append(f'tl.to("#{sid}-st{i}", {{ opacity: 0, y: -16, duration: 0.3, ease: "power2.in" }}, {s["steps"][i + 1][0] - 0.32});')
    if s.get("popup"):
        p = s["popup"]; a = p["start"]; b = a + p["dur"]
        js.append(f'tl.to("#{sid}-pop-dim", {{ opacity: 1, duration: 0.5 }}, {a - 0.3});')
        js.append(f'tl.fromTo("#{sid}-pop", {{ opacity: 0, scale: 0.8, y: 40 }}, {{ opacity: 1, scale: 1, y: 0, duration: 0.7, ease: "back.out(1.4)" }}, {a - 0.2});')
        js.append(f'tl.to("#{sid}-pop", {{ opacity: 0, scale: 0.92, duration: 0.45, ease: "power2.in" }}, {b - 0.4});')
        js.append(f'tl.to("#{sid}-pop-dim", {{ opacity: 0, duration: 0.5 }}, {b - 0.3});')
    js.append(f'tl.to(["#{sid}-win", "#{sid}-rail", "#{sid}-chap", "#{sid}-railhead"], {{ opacity: 0, duration: 0.45, ease: "power2.in" }}, {s["dur"] - 0.45});')
    js.append(f'window.__timelines["{sid}"] = tl;')
    html = f"""<!doctype html>
<html>
  <head><meta charset="UTF-8" /></head>
  <body>
    <template>
      <style>{FONTS}{css}
      </style>
      <div id="root" data-composition-id="{sid}" data-width="1920" data-height="1080">
        <div id="{sid}-grid"></div>
        <div id="{sid}-chap"><span class="tag">{ch_id}</span><span class="nm">{ch_name}</span></div>
        <div id="{sid}-railhead">WORKFLOW · LIVE</div>
        <div id="{sid}-win">
          <div id="{sid}-bar"><span class="d"></span><span class="d"></span><span class="d"></span><span class="u">{s["url"]}</span></div>
          <div id="{sid}-view"><div id="{sid}-zoom"><div id="{sid}-zin">
            {base}
            {"".join(vids)}
          </div></div></div>
        </div>
        <div id="{sid}-rail">{steps_html}</div>{popup}
      </div>
      <script>
        (function () {{
          {chr(10).join("          " + l for l in js).strip()}
        }})();
      </script>
    </template>
  </body>
</html>
"""
    (ROOT / "compositions" / f"{sid}.html").write_text(html)


for sid, s in SCENES.items():
    build(sid, s)
print("ok", list(SCENES))

